const electron=require('electron'),{app,BrowserWindow}=electron,fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),{createHash}=require('node:crypto')
const {HtmlVisualEditors,WORLD}=require('../../desktop/services/html-visual-editor.cjs')
const out=path.resolve(__dirname,'../../qa-artifacts/html-editor-compat');fs.mkdirSync(out,{recursive:true});const work=fs.mkdtempSync(path.join(out,'run-'))
app.setPath('userData',path.join(work,'profile'));app.disableHardwareAcceleration()
const hash=f=>createHash('sha256').update(fs.readFileSync(f)).digest('hex')
const delay=ms=>new Promise(r=>setTimeout(r,ms))
async function main(){
 await app.whenReady();const win=new BrowserWindow({show:false,width:1200,height:850,webPreferences:{sandbox:true,contextIsolation:true,nodeIntegration:false,offscreen:true}}),wc=win.webContents
 const js=code=>wc.executeJavaScriptInIsolatedWorld(WORLD,[{code}]),page=code=>wc.executeJavaScript(code)
 const file=path.join(work,'dynamic.html'),original='<!doctype html><html><head><meta charset="utf-8"><style>body{padding:90px;font:16px sans-serif}#note{width:650px}#chart{height:180px;background:#eee}</style></head><body><h1>标题 <span>副标题</span></h1><p id="note"></p><div id="cards"></div><div id="chart"></div><p id="seed">原始快照</p><script>window.repaintSeed=()=>document.querySelector("#seed").textContent="原始快照";repaintSeed();window.render=()=>{document.querySelector("#note").innerHTML="经营 <b>40.3 万元</b>，增长 <b>9.9%</b>";document.querySelector("#cards").innerHTML="<div><span class=amount>40.3 万元</span></div><div><span>第二项</span></div><div><span>第三项</span></div>"};render();document.querySelector("#chart").appendChild(document.createElement("canvas"));window.runs=(window.runs||0)+1;</script></body></html>'
 fs.writeFileSync(file,original);await win.loadFile(file)
 async function start(){await js(`globalThis.attach=Element.prototype.attachShadow;Element.prototype.attachShadow=function(o){const r=attach.call(this,o);globalThis.editorRoot=r;return r};true`);const editors=new HtmlVisualEditors(electron),state=await editors.start({conversationId:'a',file,view:win,roots:[work],workspace:work,window:win});const session=editors.get('a',state.sessionId);clearInterval(session.timer);return {editors,state,session}}
 let {editors,state,session}=await start()
 await page(`location.hash='s2'`);await delay(30)
 await editors.collect(session)
 await js(`__stableHtmlEditor.choose('#note');true`)
 const position=await js(`(()=>{const r=editorRoot.querySelector('.bar').getBoundingClientRect(),s=document.querySelector('#note').getBoundingClientRect();return {x:r.x,y:r.y,width:r.width,height:r.height,bottom:r.bottom,top:s.top,text:!editorRoot.querySelector('.text-tools').hidden,image:!editorRoot.querySelector('.image-tools').hidden,ai:editorRoot.querySelector('[data-panel=ai]').hidden}})()`)
 assert.ok(position.bottom<position.top);assert.ok(position.width<600&&position.height<=40);assert.ok(position.text&&!position.image&&position.ai)
 // Real mouse coordinates inside a nested text node must produce a caret, not select all.
 const caret=await js(`(()=>{const el=document.querySelector('#note b'),r=document.createRange();r.setStart(el.firstChild,2);r.setEnd(el.firstChild,3);const b=r.getBoundingClientRect(),x=b.x+1,y=b.y+b.height/2;el.dispatchEvent(new MouseEvent('click',{bubbles:true,clientX:x,clientY:y}));const single=!el.isContentEditable;el.dispatchEvent(new MouseEvent('dblclick',{bubbles:true,clientX:x,clientY:y}));const s=getSelection();return {single,editing:el.isContentEditable,collapsed:s.isCollapsed,offset:s.anchorOffset,node:s.anchorNode.textContent}})()`)
 assert.ok(caret.single&&caret.editing&&caret.collapsed);assert.equal(caret.node,'40.3 万元');assert.ok(caret.offset>=2&&caret.offset<=3,JSON.stringify(caret))
 await js(`__stableHtmlEditor.choose('#note');editorRoot.querySelector('[data-menu=sizes]').click();true`)
 const menu=await js(`(()=>{const p=editorRoot.querySelector('[data-panel=sizes]'),list=p.querySelector('.menu-list'),buttons=[...list.children],anchor=editorRoot.querySelector('[data-menu=sizes]').getBoundingClientRect(),chevron=editorRoot.querySelector('[data-menu=sizes] svg').getBoundingClientRect();return {width:p.offsetWidth,scroll:list.scrollHeight>list.clientHeight,rows:buttons[1].offsetTop>buttons[0].offsetTop,left:p.getBoundingClientRect().x,anchor:anchor.x,center:Math.abs(chevron.y+chevron.height/2-anchor.y-anchor.height/2)}})()`)
 assert.equal(menu.width,200);assert.ok(menu.scroll&&menu.rows&&menu.center<1);assert.ok(Math.abs(menu.left-menu.anchor)<1)
 await delay(100);fs.writeFileSync(path.join(out,'font-menu.png'),(await wc.capturePage()).toPNG())
 await js(`editorRoot.querySelector('[data-panel=sizes] [data-value="24px"]').click();const input=editorRoot.querySelector('[data-style="font-size"]');input.value='23';input.dispatchEvent(new Event('change'));editorRoot.querySelector('[data-menu=align]').click();true`)
 assert.equal(await page(`getComputedStyle(document.querySelector('#note')).fontSize`),'23px')
 const align=await js(`(()=>{const p=editorRoot.querySelector('[data-panel=align]');return {width:p.offsetWidth,icons:p.querySelectorAll('button svg').length,selected:p.querySelector('[aria-pressed=true]').textContent}})()`)
 assert.equal(align.width,174);assert.equal(align.icons,4);assert.equal(align.selected,'左对齐')
 await delay(100);fs.writeFileSync(path.join(out,'alignment-menu.png'),(await wc.capturePage()).toPNG())
 await js(`editorRoot.querySelector('[data-panel=align] [data-value=center]').click();__stableHtmlEditor.run('aiPanel');true`)
 assert.equal(await page(`getComputedStyle(document.querySelector('#note')).textAlign`),'center')
 const aiPanel=await js(`(()=>{const p=editorRoot.querySelector('[data-panel=ai]');return {height:p.offsetHeight,width:p.offsetWidth,inputs:p.querySelectorAll('input').length,buttons:p.querySelectorAll('button').length,textarea:!!p.querySelector('textarea'),disabled:p.querySelector('button').disabled}})()`)
 assert.ok(aiPanel.height<=50&&aiPanel.width===250&&aiPanel.inputs===1&&aiPanel.buttons===1&&!aiPanel.textarea&&aiPanel.disabled)
 await delay(100);fs.writeFileSync(path.join(out,'ai-input.png'),(await wc.capturePage()).toPNG())
 await js(`editorRoot.querySelector('.ai').value='修改这段文字';editorRoot.querySelector('.ai').dispatchEvent(new Event('input'));editorRoot.querySelector('.ai').dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',ctrlKey:true,bubbles:true}));true`)
 await editors.flush(session)
 assert.equal(session.deliveries.length,1);assert.equal(session.deliveries[0].send,false);assert.equal(session.deliveries[0].attachments[0].path,file)
 const crop=electron.nativeImage.createFromPath(session.deliveries[0].attachments[1].path).getSize();const capture=await wc.capturePage(),fullSize=electron.nativeImage.createFromBuffer(capture.toPNG()).getSize(),viewportWidth=await page('innerWidth'),scale=fullSize.width/viewportWidth;assert.ok(Math.abs(crop.width-650*scale)<=3&&crop.height<100*scale,JSON.stringify({crop,scale,viewportWidth,nativeSize:capture.getSize(),fullSize}))
 await js(`__stableHtmlEditor.run('style',{name:'text-align',value:'left'});true`);await editors.flush(session)
 assert.deepEqual(await js(`({text:editorRoot.querySelector('.status').textContent,visible:!editorRoot.querySelector('.notice').hidden})`),{text:'已自动保存',visible:true})
 await js(`document.querySelector('#note').dispatchEvent(new MouseEvent('dblclick',{bubbles:true}));document.querySelector('#note b').textContent='30 万元';document.querySelector('#note').dispatchEvent(new InputEvent('input',{bubbles:true}));true`)
 await editors.flush(session);assert.ok(fs.readFileSync(file,'utf8').includes('stable-visual-edits'));assert.equal(await page(`document.querySelector('#note b').textContent`),'30 万元')
 await js(`__stableHtmlEditor.choose('#seed');__stableHtmlEditor.run('text','保留快照修改');true`);await editors.flush(session)
 await js(`__stableHtmlEditor.choose('#cards .amount');__stableHtmlEditor.run('text','99 万元');__stableHtmlEditor.run('style',{name:'font-size',value:'30px'});true`);await editors.flush(session)
 await js(`__stableHtmlEditor.choose('#note');const r=document.createRange();r.setStart(document.querySelector('#note').firstChild,0);r.setEnd(document.querySelector('#note').firstChild,2);getSelection().removeAllRanges();getSelection().addRange(r);__stableHtmlEditor.run('style',{name:'color',value:'rgb(255, 0, 0)'});getSelection().removeAllRanges();true`);await editors.flush(session);assert.equal(await page(`getComputedStyle(document.querySelector('#note span')).color`),'rgb(255, 0, 0)')
 await js(`__stableHtmlEditor.choose('h1');__stableHtmlEditor.run('text','标题已修改');true`);await editors.flush(session)
 await js(`__stableHtmlEditor.run('undo');true`);await editors.flush(session);assert.equal(await page(`document.querySelector('h1').textContent`),'标题 副标题')
 await js(`__stableHtmlEditor.run('redo');true`);await editors.flush(session)
 await js(`__stableHtmlEditor.choose('#cards > div:nth-child(2)');__stableHtmlEditor.run('delete');true`);await editors.flush(session)
 await editors.stop('a',state.sessionId);await win.loadFile(file);await delay(100)
 assert.equal(await page(`document.querySelector('#note b').textContent`),'30 万元');assert.equal(await page(`document.querySelector('#cards .amount').textContent`),'99 万元');assert.equal(await page(`getComputedStyle(document.querySelector('#cards .amount')).fontSize`),'30px');assert.equal(await page(`document.querySelector('h1').textContent`),'标题已修改');assert.equal(await page('window.runs'),1);assert.equal(await page(`document.querySelectorAll('canvas').length`),1)
 assert.equal(await page(`document.querySelector('#seed').textContent`),'保留快照修改');await page('window.repaintSeed()');await delay(50);assert.equal(await page(`document.querySelector('#seed').textContent`),'保留快照修改')
 await page('window.render()');await delay(100);assert.equal(await page(`getComputedStyle(document.querySelector('#cards > div:nth-child(2)')).display`),'none');assert.notEqual(await page(`getComputedStyle(document.querySelector('#cards > div:nth-child(3)')).display`),'none');assert.equal(await page(`document.querySelector('#note b').textContent`),'30 万元');assert.equal(await page(`document.querySelector('#cards .amount').textContent`),'99 万元')
 ;({editors,state,session}=await start());await js(`__stableHtmlEditor.choose('#note b');__stableHtmlEditor.run('text','35 万元');true`);await editors.flush(session);await editors.stop('a',state.sessionId);await win.loadFile(file);await delay(100);assert.equal(await page(`document.querySelector('#note b').textContent`),'35 万元')
 const real=process.env.STABLE_EDITOR_REPORT;let report
 if(real&&fs.existsSync(real)){
   const before=hash(real),copy=path.join(work,'real-report.html');fs.copyFileSync(real,copy);await win.loadFile(copy);await delay(300)
   await js(`globalThis.attach=Element.prototype.attachShadow;Element.prototype.attachShadow=function(o){const r=attach.call(this,o);globalThis.editorRoot=r;return r};true`)
   const manager=new HtmlVisualEditors(electron),entry=await manager.start({conversationId:'actual',file:copy,view:win,roots:[work],workspace:work,window:win}),s=manager.get('actual',entry.sessionId);clearInterval(s.timer)
   await js(`__stableHtmlEditor.choose('.brand');__stableHtmlEditor.run('text','打杂陈·测试标题');true`);await manager.flush(s)
   await js(`__stableHtmlEditor.choose('#heroNote');__stableHtmlEditor.run('style',{name:'font-size',value:'18px'});document.querySelector('#heroNote').dispatchEvent(new MouseEvent('dblclick',{bubbles:true}));document.querySelector('#heroNote b').textContent='30%';document.querySelector('#heroNote').dispatchEvent(new InputEvent('input',{bubbles:true}));true`);await manager.flush(s)
   await js(`__stableHtmlEditor.choose('#heroKpis .hk:nth-child(2) .hk-v');__stableHtmlEditor.run('text','30 万元');true`);await manager.flush(s)
   fs.writeFileSync(path.join(out,'actual-toolbar.png'),(await wc.capturePage()).toPNG())
   await manager.stop('actual',entry.sessionId);await win.loadFile(copy);await delay(300)
   assert.equal(await page(`document.querySelector('#heroNote b').textContent`),'30%');assert.equal(await page(`document.querySelector('#heroKpis .hk:nth-child(2) .hk-v').textContent`),'30 万元');assert.equal(await page(`getComputedStyle(document.querySelector('#heroNote')).fontSize`),'18px');assert.equal(await page(`document.querySelector('.brand').textContent`),'打杂陈·测试标题');assert.equal(hash(real),before)
   report={source:real,sourceHash:before,copy,unchanged:true}
 }
 const hashReport=process.env.STABLE_EDITOR_HASH_REPORT;let hashReportResult
 if(hashReport&&fs.existsSync(hashReport)){
   const before=hash(hashReport),copy=path.join(work,'hash-report.html');fs.copyFileSync(hashReport,copy);await win.loadFile(copy);await delay(300)
   await js(`globalThis.attach=Element.prototype.attachShadow;Element.prototype.attachShadow=function(o){const r=attach.call(this,o);globalThis.editorRoot=r;return r};true`)
   const manager=new HtmlVisualEditors(electron),entry=await manager.start({conversationId:'hash-report',file:copy,view:win,roots:[work],workspace:work,window:win}),s=manager.get('hash-report',entry.sessionId);clearInterval(s.timer)
   await page(`location.hash='s2'`);await delay(900)
   await js(`__stableHtmlEditor.choose('#s2 h2');__stableHtmlEditor.run('text','经营问题测试');__stableHtmlEditor.run('aiPanel');editorRoot.querySelector('.ai').value='修改这一处标题';editorRoot.querySelector('.ai').dispatchEvent(new Event('input'));true`)
   await delay(100);fs.writeFileSync(path.join(out,'hash-report-ai.png'),(await wc.capturePage()).toPNG())
   await js(`editorRoot.querySelector('[data-action=draft]').click();true`);await manager.flush(s)
   assert.equal(s.deliveries.length,1);assert.equal(s.deliveries[0].attachments[0].path,copy);assert.equal(s.deliveries[0].send,false)
   fs.copyFileSync(s.deliveries[0].attachments[1].path,path.join(out,'hash-report-selection.png'))
   await manager.stop('hash-report',entry.sessionId);await win.loadFile(copy);assert.equal(await page(`document.querySelector('#s2 h2').textContent`),'经营问题测试');assert.equal(hash(hashReport),before)
   hashReportResult={source:hashReport,sourceHash:before,copy,unchanged:true,chatAttachments:s.deliveries[0].attachments.map(a=>a.type)}
 }
 fs.writeFileSync(path.join(out,'result.json'),JSON.stringify({passed:true,position,report,hashReportResult,caret,menu,align,aiPanel,checks:['hash navigation preserves editor and chat','single click selects and double click places caret','scrolling font size and alignment menus','draft only HTML plus cropped selection plus prompt','visible autosave notification','rich nested text','generated KPI text and styles','reload persistence','page rerender persistence','undo redo','reopen edit','source scripts run once','original report preserved']},null,2));win.destroy();console.log('HTML_EDITOR_COMPAT_PASSED');app.exit(0)
}
main().catch(e=>{console.error(e.stack);app.exit(1)})
